'use strict';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let page='overview',raw=[],records=[],filename='7f18f899_20261015_102421.csv',timer=null,replayTime=0,selectedRaid=0,logPage=0,logQuery='',logCategory='all',logMessage='all';
const titles={overview:['플레이테스트 개요','수집된 로그로 확인하는 상점 실적과 습격 결과'],shop:['상점 운영','실제 판매 기록과 작업대 체류 시간을 분석합니다.'],raid:['야간 습격','실제 위치 · 카메라 방향 · 상태 · 이벤트를 같은 시간축에서 확인하세요.'],weapons:['총기 · 모듈','현재 파일에서 확인할 수 있는 정보와 미수집 항목입니다.'],logs:['이벤트 탐색기','원본 CSV의 모든 행을 검색하고 상세 JSON을 확인하세요.'],schema:['수집 항목 · 정의','분석 기준과 데이터 누락을 확인합니다.']};
const sum=(a,f)=>a.reduce((s,r)=>s+f(r),0),num=n=>Number(n).toLocaleString('ko-KR',{maximumFractionDigits:2}),sec=n=>Number.isFinite(n)?num(n)+'초':'—',fmt=t=>{if(!Number.isFinite(t))return '시간 오류';return new Date(t+($('#tz').value==='KST'?32400000:0)).toISOString().replace('T',' ').slice(0,23)},short=t=>fmt(t).slice(11,19);
function normalize(rows){return rows.map((r,i)=>{let d={},bad=false;try{d=r.data_json?JSON.parse(r.data_json):{}}catch{bad=true}if(!d||typeof d!=='object'||Array.isArray(d)){bad=true;d={}}let t=Date.parse((r.timestamp_utc||'').replace(' ','T')+(/(?:Z|[+-]\d\d:\d\d)$/.test(r.timestamp_utc||'')?'':'Z'));return {...r,d,t,bad,index:i};}).sort((a,b)=>a.t-b.t||a.index-b.index)}
function filtered(){let scene=$('#scene').value;return records.filter(r=>scene==='all'||r.scene===scene)}
function analyze(rr){const sales=rr.filter(r=>r.category==='Shop'&&r.message==='총 판매'),validSales=sales.filter(r=>typeof r.d.price==='number'&&Number.isFinite(r.d.price)),states=rr.filter(r=>r.category==='NightRaid'&&r.message==='플레이어 상태'&&typeof r.d.time==='number'&&r.d.position&&Number.isFinite(r.d.position.x)&&Number.isFinite(r.d.position.z));let open=null,visits=[],unmatched=0;for(let r of rr.filter(r=>r.category==='Workshop')){if(r.message==='작업대 진입'){if(open)unmatched++;open=r}else if(r.message==='작업대 퇴장'){if(open&&open.scene===r.scene&&r.t>=open.t){visits.push({start:open,end:r,duration:(r.t-open.t)/1000});open=null}else unmatched++}}if(open)unmatched++;
let raids=[],current=null;for(let r of rr.filter(r=>r.category==='NightRaid')){if(r.message==='습격 시작'){current={start:r,rows:[],end:null};raids.push(current)}if(!current){current={start:null,rows:[],end:null};raids.push(current)}current.rows.push(r);if(r.message==='습격 사망'||r.message==='탈출 성공'||r.message==='습격 성공'||r.d.survived===true||r.d.survived===false){current.end=r;current=null}}raids=raids.map(a=>({...a,states:a.rows.filter(r=>states.includes(r)).sort((a,b)=>a.d.time-b.d.time)}));return {rr,sales,validSales,states,visits,unmatched,raids,blocks:rr.filter(r=>r.category==='NightRaid'&&r.message==='블록 파괴'),revenue:sum(validSales,r=>r.d.price)}}
function card(title,caption,body,extra=''){return `<section class="card"><div class="cardhead"><h2>${title}</h2>${extra}</div><div class="caption">${caption}</div>${body}</section>`}function kpi(label,value,unit,note){return `<div class="card"><div class="metric-label">${label}</div><div class="metric">${value} <small>${unit}</small></div><div class="foot">${note}</div></div>`}function empty(text){return `<div class="empty">${text}</div>`}function table(head,rows){return `<div class="scroll"><table><thead><tr>${head.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`}function line(k,v){return `<div class="minirow"><span>${k}</span><b>${v}</b></div>`}
function header(a){return `<div class="kpis">${kpi('총 판매',num(a.sales.length),'건','Shop / 총 판매 이벤트만 집계')}${kpi('판매액 합계',num(a.revenue),'','보유 금액 · 순이익과는 다른 값')}${kpi('플레이어 상태',num(a.states.length),'개','유효 위치 · 게임 시간 기록')}${kpi('블록 파괴',num(a.blocks.length),'건',new Set(a.blocks.map(r=>r.d.blockId).filter(Boolean)).size.toLocaleString()+'개 고유 블록 ID')}</div>`}
function salesChart(a){if(!a.validSales.length)return empty('선택한 씬에 판매 데이터가 없습니다.');let v=a.validSales,max=Math.max(...v.map(r=>r.d.price),1),w=520/v.length;return `<div class="chart salechart"><svg viewBox="0 0 600 225" role="img" aria-label="판매 이벤트별 실제 판매액"><g stroke="#2a3039">${[30,70,110,150,190].map(y=>`<path d="M55 ${y}H590"/>`).join('')}</g>${[0,1,2,3,4].map(i=>`<text x="0" y="${194-i*40}">${num(max*i/4)}</text>`).join('')}${v.map((r,i)=>`<rect x="${60+i*w}" y="${190-r.d.price/max*160}" width="${Math.max(1,w-10)}" height="${r.d.price/max*160}" fill="#c6ef83" rx="2"><title>${short(r.t)} · ${num(r.d.price)}</title></rect>${i%Math.max(1,Math.ceil(v.length/10))===0?`<text x="${60+i*w}" y="213">#${i+1}</text>`:''}`).join('')}</svg></div><div class="caption">가로축: 판매 순서 · 세로축: 판매액 · 막대에 마우스를 올려 상세 확인</div>`}
function counts(a){const c={};a.rr.forEach(r=>c[r.category]=(c[r.category]||0)+1);let entries=Object.entries(c).sort((a,b)=>b[1]-a[1]),m=Math.max(...entries.map(x=>x[1]),1);return entries.map(([k,v])=>`<div class="barrow"><span>${esc(k)}</span><div class="track"><div style="width:${v/m*100}%"></div></div><span>${num(v)}</span></div>`).join('')||empty('해당 기록 없음')}
function salesTable(a){return table(['시간 ('+$('#tz').value+')','판매액','조건 만족','태그 수'],a.sales.map(r=>`<tr data-row="${r.index}" tabindex="0"><td>${short(r.t)}</td><td class="green">${typeof r.d.price==='number'?num(r.d.price):'미기록'}</td><td>${r.d.satisfied===true?'만족':r.d.satisfied===false?'불만족':'미기록'}</td><td>${r.d.tagCount??'미기록'}</td></tr>`))}
function raidsTable(a){return a.raids.length?table(['시작 시간','씬','종료 상태','게임 내 소요','기록 처치 수'],a.raids.map((r,i)=>`<tr data-raid="${i}" tabindex="0"><td>${r.start?short(r.start.t):'시작 미기록'}</td><td>${esc(r.start?.d.scene||r.rows[0]?.scene)}</td><td><span class="pill ${r.end?.d.survived===false?'warn':''}">${r.end?esc(r.end.message):'종료 미기록'}</span></td><td>${sec(r.end?.d.duration)}</td><td>${r.end?.d.enemyKills??'—'}</td></tr>`)):empty('선택한 씬에 습격 기록이 없습니다.')}
function render(){clearInterval(timer);timer=null;let a=analyze(filtered());$('#title').textContent=titles[page][0];$('#subtitle').textContent=titles[page][1];document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#source').textContent=filename+' · '+num(a.rr.length)+' / '+num(records.length)+'행';let ts=records.map(r=>r.t).filter(Number.isFinite);$('#range').textContent=ts.length?fmt(Math.min(...ts))+' – '+short(Math.max(...ts))+' '+$('#tz').value:'';let html='';
if(page==='overview')html=header(a)+`<div class="grid">${card('판매액 추이','중복 Unity 콘솔 출력은 매출에 포함하지 않습니다.',salesChart(a),'<span class="tag">ACTUAL</span>')}${card('로그 구성','선택한 씬의 원본 행 수',counts(a))}</div><div class="grid">${card('습격 결과','행을 선택하면 실제 이동 경로를 재생합니다.',raidsTable(a))}${card('데이터로 확인 가능한 범위','결측값은 0으로 대체하지 않습니다.',line('판매 조건 만족',a.sales.length?`${a.sales.filter(r=>r.d.satisfied===true).length} / ${a.sales.length}건`:'미수집')+line('작업대 진입 → 퇴장',a.visits.length+'쌍')+line('제출 · 휴대 총기 코드','미수집')+line('사격 테스트 · 사격 인풋','미수집')+`<div class="insight"><strong>판매 조건 만족 ≠ 전체 주문 성공률</strong><p>전체 주문 수가 없으므로 주문 성공률을 계산하지 않습니다. 총기 및 사격 분석도 해당 이벤트가 필요합니다.</p></div>`)}</div>`;
if(page==='shop')html=`<div class="kpis">${kpi('판매 이벤트',num(a.sales.length),'건','Unity 중복 출력 제외')}${kpi('판매액 합계',num(a.revenue),'','유효 price 합계')}${kpi('평균 작업대 체류',a.visits.length?num(sum(a.visits,v=>v.duration)/a.visits.length):'—','초',a.visits.length+'개 완결된 진입 / 퇴장 쌍')}${kpi('판매 조건 만족',a.sales.length?num(a.sales.filter(r=>r.d.satisfied===true).length/a.sales.length*100):'—','%',a.sales.length+'건 판매 중 satisfied=true 비율')}</div><div class="grid">${card('판매 기록','행을 선택하면 원본 데이터가 열립니다.',salesTable(a))}${card('작업대 체류 시간','같은 씬에서 시간순으로 진입과 퇴장을 연결합니다.',table(['진입','퇴장','체류 시간'],a.visits.map(v=>`<tr><td>${short(v.start.t)}</td><td>${short(v.end.t)}</td><td>${sec(v.duration)}</td></tr>`))+`<div class="insight"><strong>주문별 연결은 불가능합니다.</strong><p>주문 ID와 총기 코드가 없습니다. 판매와 작업대 이용은 별도 목록으로 표시합니다. 연결되지 않은 진입·퇴장 ${a.unmatched}건.</p></div>`)}</div>`;
if(page==='raid')html=raidView(a);
if(page==='weapons')html=`<div class="statusbox">이 파일에는 제출·휴대 총기 코드와 모듈 구성이 없습니다. 가상의 사용 순위는 표시하지 않습니다.</div><div class="grid">${card('제출 총기','총 판매 이벤트는 '+a.sales.length+'건입니다.',line('확인 가능','판매액 / 조건 만족 / 태그 수')+line('총기 코드','미수집')+line('모듈 사용 비중','계산 불가'))}${card('습격 보상','종료 이벤트의 원본 필드입니다. 휴대 장비를 의미하지 않습니다.',a.raids.map(r=>r.end?line('moduleCrateRewards',esc(JSON.stringify(r.end.d.moduleCrateRewards??null)))+line('moduleCrateCredits',num(r.end.d.moduleCrateCredits??0))+line('materialCrateCredits',num(r.end.d.materialCrateCredits??0)):empty('종료 이벤트 없음')).join('')||empty('습격 데이터 없음'))}</div>${card('다음 수집 항목','실제 총기 분석을 연결하려면',`<div class="schema"><b>판매 시</b><p>orderId, gunCode, moduleIds를 함께 기록합니다.</p></div><div class="schema"><b>습격 시작 시</b><p>gunCode, moduleIds를 기록하여 실제 휴대 장비를 식별합니다.</p></div><div class="schema"><b>모듈 ID 사전</b><p>모듈 ID와 표시 이름·종류를 연결해야 의미 있는 모듈별 순위를 보여줄 수 있습니다.</p></div>`)}`;
if(page==='logs')html=card('원본 이벤트 탐색','모든 CSV 행을 보존합니다. 집계에서 제외한 Unity 출력도 표시합니다.',`<div class="filters" style="margin-top:18px"><input class="search" id="query" placeholder="메시지 · JSON · ID 검색" aria-label="로그 검색" value="${esc(logQuery)}"><select id="category" aria-label="카테고리"><option value="all">전체 카테고리</option>${[...new Set(a.rr.map(r=>r.category))].map(c=>`<option ${logCategory===c?'selected':''} value="${esc(c)}">${esc(c)}</option>`).join('')}</select><select id="message" aria-label="이벤트"><option value="all">전체 이벤트</option>${[...new Set(a.rr.map(r=>r.message))].map(c=>`<option ${logMessage===c?'selected':''} value="${esc(c)}">${esc(c)}</option>`).join('')}</select></div><div id="logtable"></div><div class="pager"><button class="outline" id="prev">← 이전</button><span id="pagenum"></span><button class="outline" id="next">다음 →</button></div>`);
if(page==='schema')html=card('현재 파일 분석 기준','불명확한 정보는 추정하지 않습니다.',`<div class="schema"><b>원본 구조 · ${num(records.length)}행</b><p>timestamp_utc, level, category, scene, message, data_json, stack_trace<br>JSON 파싱 오류 ${records.filter(r=>r.bad).length}행 · 시간 파싱 오류 ${records.filter(r=>!Number.isFinite(r.t)).length}행</p></div><div class="schema"><b>시간 기준</b><p>timestamp_utc는 UTC로 해석하여 화면에서 KST/UTC를 전환합니다. 리플레이는 data_json.time의 게임 내 초를 사용합니다. 서로 다른 두 시간축을 혼합하지 않습니다.</p></div><div class="schema"><b>상점 집계</b><p>category=Shop, message=총 판매만 매출에 포함합니다. Unity 콘솔 출력은 중복 집계하지 않습니다. satisfied는 판매 조건 만족 여부이며 전체 주문 성공률이 아닙니다. 체류 시간은 같은 씬의 연속 진입·퇴장 쌍으로 계산합니다.</p></div><div class="schema"><b>습격 리플레이</b><p>플레이어 상태의 실제 XZ 좌표를 동일 축척으로 표시합니다. 맵 구조물 데이터가 없어 배경 지형은 표시하지 않습니다. 카메라 Y 회전은 방향 부채꼴로 표시합니다. 시간 사이에는 직전 샘플을 유지하며, 종료 이벤트의 체력을 별도 반영합니다. 블록 파괴에는 위치가 없으므로 지도에 임의로 배치하지 않습니다.</p></div><div class="schema"><b>상자 데이터</b><p>remainingModuleCrates와 remainingMaterialCrates를 각각 표시합니다. 두 값을 금고 수로 이름 바꾸지 않습니다. 종료 이벤트의 보상은 기록된 값이며, 사망 후 실제 지급 여부는 이 파일로 확인할 수 없습니다.</p></div><div class="schema"><b>데이터 범위 · 파일 단위</b><p>이 파일에는 명시적 player_id/session_id가 없습니다. 파일을 분석 단위로 사용하고 습격 시작·종료로 구간을 구분합니다. 이벤트 탐색에서 모든 원본 행을 확인할 수 있습니다.</p></div><div class="schema"><b>CSV 불러오기</b><p>같은 7개 열을 가진 CSV를 브라우저에서 분석합니다. 새 파일은 서버로 업로드하지 않으며 새로고침하면 기본 첨부 데이터로 돌아옵니다. 새 이벤트는 탐색기에 표시되지만 집계는 위에 정의한 이벤트명에 적용됩니다.</p></div>`);
$('#content').innerHTML=html;bindRows();if(page==='raid')bindReplay(a);if(page==='logs'){logPage=0;drawLogs();$('#query').oninput=e=>{logQuery=e.target.value;logPage=0;drawLogs()};$('#category').onchange=e=>{logCategory=e.target.value;logPage=0;drawLogs()};$('#message').onchange=e=>{logMessage=e.target.value;logPage=0;drawLogs()};$('#prev').onclick=()=>{logPage--;drawLogs()};$('#next').onclick=()=>{logPage++;drawLogs()}}}
function bindRows(){document.querySelectorAll('[data-row]').forEach(b=>{b.onclick=()=>detail(+b.dataset.row);b.onkeydown=e=>{if(e.key==='Enter')b.click()}});document.querySelectorAll('[data-raid]').forEach(b=>{b.onclick=()=>{selectedRaid=+b.dataset.raid;page='raid';render()};b.onkeydown=e=>{if(e.key==='Enter')b.click()}})}
function detail(index){let r=records.find(r=>r.index===index);$('#detailbody').innerHTML=`<div class="eyebrow">SOURCE ROW ${index+2}</div><h2>${esc(r.message)}</h2><p>${fmt(r.t)} ${$('#tz').value} · ${esc(r.category)} / ${esc(r.scene)}</p><pre>${esc(r.data_json?JSON.stringify(r.d,null,2):'data_json 없음')}</pre>${r.bad?'<p class="orange">JSON 해석 실패 · 원본:</p><pre>'+esc(r.data_json)+'</pre>':''}${r.stack_trace?'<pre>'+esc(r.stack_trace)+'</pre>':''}`;$('#detail').showModal()}
function visibleLogs(){let q=logQuery.toLowerCase();return filtered().filter(r=>(logCategory==='all'||r.category===logCategory)&&(logMessage==='all'||r.message===logMessage)&&[r.message,r.data_json,r.scene,r.category,r.stack_trace].join(' ').toLowerCase().includes(q))}
function drawLogs(){let arr=visibleLogs(),pages=Math.max(1,Math.ceil(arr.length/50));logPage=Math.max(0,Math.min(pages-1,logPage));$('#logtable').innerHTML=table(['원본 행','시간','카테고리','메시지','데이터 요약'],arr.slice(logPage*50,logPage*50+50).map(r=>`<tr data-row="${r.index}" tabindex="0"><td>${r.index+2}</td><td>${fmt(r.t).slice(11)}</td><td>${esc(r.category)}</td><td>${esc(r.message)}</td><td class="caption">${esc((r.data_json||'—').slice(0,100))}${r.data_json.length>100?'…':''}</td></tr>`))+(arr.length?'':empty('검색 결과가 없습니다.'));$('#pagenum').textContent=`${num(arr.length)}행 · ${logPage+1} / ${pages}페이지`;$('#prev').disabled=logPage===0;$('#next').disabled=logPage===pages-1;bindRows()}
function chosen(a){return a.raids[Math.min(selectedRaid,a.raids.length-1)]}function duration(r){return Math.max(r.end?.d.duration||0,...r.states.map(s=>s.d.time),0)}
function stateGraph(r){if(!r.states.length)return empty('상태 샘플 없음');let total=duration(r)||1,maximum=maxState(r);const series=[['health','체력','#c6ef83'],['remainingModuleCrates','모듈 상자','#83b8fa'],['remainingMaterialCrates','재료 상자','#a49aff'],['tanks','탱크','#efaf77'],['helicopters','헬기','#ef84a2']];return `<div class="legend">${series.map(([k,n,c])=>`<span><i style="background:${c}"></i>${n}</span>`).join('')}</div><div class="chart"><svg viewBox="0 0 700 240" role="img" aria-label="게임 시간별 체력, 상자와 적 수">${[0,1,2,3,4,5].map(i=>`<path d="M40 ${200-i*34}H680" stroke="#2a3039"/><text x="8" y="${204-i*34}">${num(i*maximum/5)}</text><text x="${40+i*128}" y="225">${num(total*i/5)}s</text>`).join('')}${series.map(([key,name,color])=>{let pts=r.states.filter(s=>typeof s.d[key]==='number'),path='',last;for(let s of pts){let x=40+s.d.time/total*640,y=200-s.d[key]/maximum*170;if(last===undefined)path=`M${x} ${y}`;else if(s.d[key]!==last)path+=`H${x}V${y}`;last=s.d[key]}if(pts.length)path+=`H${40+pts.at(-1).d.time/total*640}`;if(key==='health'&&r.end&&typeof r.end.d.health==='number')path+=`H${40+(r.end.d.time??total)/total*640}V${200-r.end.d.health/maximum*170}`;return `<path d="${path}" fill="none" stroke="${color}" stroke-width="2"><title>${name}</title></path>`}).join('')}<path id="cursor" stroke="#fff" stroke-dasharray="3 4" d="M40 25V200"/></svg></div>`}function maxState(r){return Math.max(1,...r.states.flatMap(s=>['health','remainingModuleCrates','remainingMaterialCrates','tanks','helicopters'].map(k=>Number(s.d[k])||0)))}
function mapping(r){let xs=r.states.map(s=>s.d.position.x),zs=r.states.map(s=>s.d.position.z),minx=Math.min(...xs),maxx=Math.max(...xs),minz=Math.min(...zs),maxz=Math.max(...zs),scale=Math.min(500/Math.max(1,maxx-minx),290/Math.max(1,maxz-minz)),cx=(minx+maxx)/2,cz=(minz+maxz)/2;return {x:x=>300+(x-cx)*scale,z:z=>175-(z-cz)*scale,minx,maxx,minz,maxz,scale}}
function map(r){if(!r.states.length)return empty('실제 위치 샘플이 없습니다.');let m=mapping(r),points=r.states.map(s=>m.x(s.d.position.x)+','+m.z(s.d.position.z)).join(' ');return `<div class="map"><svg viewBox="0 0 600 350" role="img" aria-label="실제 플레이어 XZ 이동 경로"><defs><pattern id="grid" width="25" height="25" patternUnits="userSpaceOnUse"><path d="M25 0H0V25" fill="none" stroke="#26313b" stroke-width=".6"/></pattern></defs><rect width="600" height="350" fill="url(#grid)"/><text x="14" y="20">+Z ↑ · +X → / XZ 동일 축척</text><text x="14" y="335">X ${num(m.minx)} ~ ${num(m.maxx)} · Z ${num(m.minz)} ~ ${num(m.maxz)}</text><polyline points="${points}" fill="none" stroke="#50683c" stroke-width="2"/><polyline id="trail" fill="none" stroke="#c6ef83" stroke-width="2"/><path id="look" fill="#83b8fa" opacity=".35"/><circle cx="${m.x(r.states[0].d.position.x)}" cy="${m.z(r.states[0].d.position.z)}" r="5" fill="#83b8fa"/><circle id="player" r="6" fill="#c6ef83" stroke="#10161b" stroke-width="2"/></svg></div>`}
function raidView(a){if(!a.raids.length)return card('야간 습격','선택한 씬 기준',empty('습격 기록이 없습니다. 전체 씬 또는 습격 씬을 선택하세요.'));let r=chosen(a),end=r.end;return `<div class="filters"><label>습격 구간</label><select id="raidSelect">${a.raids.map((r,i)=>`<option value="${i}" ${i===Math.min(selectedRaid,a.raids.length-1)?'selected':''}>#${i+1} · ${esc(r.rows[0].scene)} · ${r.start?short(r.start.t):'시작 누락'}</option>`).join('')}</select><span class="pill ${end?.d.survived===false?'warn':''}">${end?esc(end.message):'종료 미기록'}</span></div><div class="kpis">${kpi('종료 소요 시간',end?.d.duration!=null?num(end.d.duration):'—','초','게임 내 duration')}${kpi('적 처치',num(r.rows.filter(s=>s.message==='적 처치').length),'건','처치 이벤트 기준')}${kpi('블록 파괴',num(r.rows.filter(s=>s.message==='블록 파괴').length),'건','파괴 이벤트 기준')}${kpi('최종 체력',end?.d.health??'—','','종료 이벤트 health')}</div><div class="grid">${card('실제 이동 경로','배경 지형 없음 · 카메라 Y 회전을 부채꼴로 표시',map(r)+`<div class="scrub"><button id="play">▶ 재생</button><input id="seek" type="range" min="0" max="${duration(r)}" step="0.02" value="0" aria-label="리플레이 시간"><select id="speed" aria-label="재생 속도"><option value="1">1×</option><option value="2">2×</option><option value=".5">0.5×</option></select><span id="clock" class="caption"></span></div><div class="replaymeta"><span>파랑: 시작점 · 부채꼴: 시선</span><span>연두: 현재 위치 · 이동</span></div>`)}${card('현재 상태','슬라이더와 그래프가 같은 게임 시간을 가리킵니다.',`<div class="metric" id="hp"></div><div id="states"></div><div id="lastEvent" class="insight"></div>`)}</div>${card('시간별 상태 변화','실측값을 계단형으로 표시 · 체력과 개수의 공통 수치 축',stateGraph(r))}<div class="grid" style="margin-top:20px">${card('주요 이벤트','블록 파괴는 우측에 누적 건수로 표시합니다.',table(['게임 시간','이벤트','적 ID'],r.rows.filter(s=>!['플레이어 상태','블록 파괴'].includes(s.message)).map(s=>`<tr data-row="${s.index}" tabindex="0"><td>${sec(s.d.time)}</td><td>${esc(s.message)}</td><td>${esc(s.d.enemyId||'—')}</td></tr>`)))}${card('기록된 종료 보상','사망 후 실제 지급 여부는 확인되지 않습니다.',line('모듈 보상 ID',esc(JSON.stringify(end?.d.moduleCrateRewards??null)))+line('모듈 상자 크레딧',end?.d.moduleCrateCredits??'—')+line('재료 상자 크레딧',end?.d.materialCrateCredits??'—')+`<div class="caption" style="margin-top:15px">적 종류별 생성은 enemyId만으로 분류하지 않습니다. 탱크·헬기 수는 상태 샘플에 기록된 값을 사용합니다.</div>`)}</div>`}
function bindReplay(a){let r=chosen(a);if(!r)return;replayTime=0;$('#raidSelect').onchange=e=>{selectedRaid=+e.target.value;render()};$('#seek').oninput=e=>{replayTime=+e.target.value;updateReplay(r)};$('#play').onclick=()=>{if(timer){clearInterval(timer);timer=null;$('#play').textContent='▶ 재생';return}if(replayTime>=duration(r))replayTime=0;let prev=performance.now();$('#play').textContent='Ⅱ 일시정지';timer=setInterval(()=>{let now=performance.now();replayTime=Math.min(duration(r),replayTime+(now-prev)/1000*Number($('#speed').value));prev=now;updateReplay(r);if(replayTime>=duration(r)){clearInterval(timer);timer=null;$('#play').textContent='↻ 다시 재생'}},40)};updateReplay(r)}
function updateReplay(r){let ss=r.states,idx=-1;for(let i=0;i<ss.length;i++){if(ss[i].d.time<=replayTime)idx=i;else break}let s=idx>=0?ss[idx]:null,end=r.end&&replayTime>=(r.end.d.time??duration(r))?r.end:null;$('#seek').value=replayTime;$('#clock').textContent=num(replayTime)+' / '+num(duration(r))+'초';$('#hp').innerHTML=(end?.d.health??s?.d.health??'—')+' <small>HP</small>';$('#states').innerHTML=s?line('모듈 / 재료 상자',(s.d.remainingModuleCrates??'—')+' / '+(s.d.remainingMaterialCrates??'—'))+line('탱크 / 헬기',(s.d.tanks??'—')+' / '+(s.d.helicopters??'—'))+line('위치 XYZ',[s.d.position.x,s.d.position.y,s.d.position.z].map(num).join(', '))+line('카메라 XYZ',[s.d.cameraRotation?.x,s.d.cameraRotation?.y,s.d.cameraRotation?.z].map(x=>x==null?'—':num(x)+'°').join(', '))+line('표시 샘플 시간',sec(s.d.time)):empty('첫 상태 샘플 이전입니다.');let blocks=r.rows.filter(s=>s.message==='블록 파괴'&&s.d.time<=replayTime).length,e=r.rows.filter(s=>!['플레이어 상태','블록 파괴','습격 시작'].includes(s.message)&&s.d.time<=replayTime).at(-1);$('#lastEvent').innerHTML=`<b>누적 블록 파괴 ${num(blocks)}건</b><p>${e?esc(e.message)+' · '+sec(e.d.time):'아직 주요 이벤트가 없습니다.'}</p>`;if($('#cursor'))$('#cursor').setAttribute('d',`M${40+replayTime/(duration(r)||1)*640} 25V200`);if(!ss.length)return;$('#player').style.display=s?'':'none';$('#look').style.display=s?'':'none';let m=mapping(r);$('#trail').setAttribute('points',ss.slice(0,idx+1).map(v=>m.x(v.d.position.x)+','+m.z(v.d.position.z)).join(' '));if(s){let x=m.x(s.d.position.x),y=m.z(s.d.position.z),yaw=(s.d.cameraRotation?.y??0)*Math.PI/180;$('#player').setAttribute('cx',x);$('#player').setAttribute('cy',y);$('#look').setAttribute('d',`M${x} ${y}L${x+Math.sin(yaw-.4)*34} ${y-Math.cos(yaw-.4)*34}L${x+Math.sin(yaw+.4)*34} ${y-Math.cos(yaw+.4)*34}Z`)}}
function parseCSV(text){text=text.replace(/^\uFEFF/,'');let rows=[],row=[],field='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(field);field=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(v=>v!==''))rows.push(row);row=[];field=''}else field+=c}if(quoted)throw Error('닫히지 않은 CSV 따옴표가 있습니다.');if(field||row.length){row.push(field);rows.push(row)}let headers=rows.shift()||[],required=['timestamp_utc','level','category','scene','message','data_json','stack_trace'];if(required.some(k=>!headers.includes(k)))throw Error('필수 열 7개가 필요합니다: '+required.join(', '));if(rows.some(r=>r.length!==headers.length))throw Error('CSV 열 수가 일치하지 않습니다.');return rows.map(r=>Object.fromEntries(headers.map((k,i)=>[k,r[i]])))}
function load(rows,name){if(!rows.length)throw Error('CSV에 데이터 행이 없습니다.');let parsed=normalize(rows);if(!parsed.some(r=>Number.isFinite(r.t)))throw Error('유효한 UTC 시간이 없습니다.');raw=rows;records=parsed;filename=name;selectedRaid=0;logPage=0;logQuery='';logCategory='all';logMessage='all';$('#scene').innerHTML='<option value="all">전체 씬</option>'+[...new Set(records.map(r=>r.scene))].map(s=>`<option value="${esc(s)}">${esc(s||'(빈 값)')}</option>`).join('');$('#status').textContent=`실제 기록 ${num(records.length)}행을 읽었습니다. ${records.filter(r=>r.bad).length?'JSON 오류 행은 원본 탐색기에서 확인하세요.':''}`;render()}
function exportCSV(){let rr=page==='logs'?visibleLogs():filtered(),headers=['timestamp_utc','level','category','scene','message','data_json','stack_trace'],quote=v=>'"'+String(v??'').replace(/"/g,'""')+'"',csv=[headers.map(quote).join(','),...rr.map(r=>headers.map(k=>quote(r[k])).join(','))].join('\r\n'),url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='armory-filtered.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render()});$('#scene').onchange=()=>{selectedRaid=0;logCategory='all';logMessage='all';render()};$('#tz').onchange=render;$('#export').onclick=exportCSV;$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{let f=e.target.files[0];if(!f)return;try{load(parseCSV(await f.text()),f.name);$('#status').textContent+=' 새 파일은 브라우저에서만 사용됩니다.'}catch(err){$('#status').textContent='불러오기 실패: '+err.message+' 기존 데이터는 유지됩니다.'}e.target.value=''};load(window.INITIAL_LOGS,filename);
